package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown on create when the supplied email is present but is not a syntactically valid address.
 * Carries the {@code email} field name so the {@link ExceptionControllerAdvice} can report it in
 * the {@code errors} array of a 400 Bad Request response, mirroring {@link InvalidTelephoneException}.
 */
public class InvalidEmailException extends RuntimeException {

    public InvalidEmailException(String message) {
        super(message);
    }
}

