38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
42	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
44	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
45	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
46	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
47	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
48	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
49	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
50	import org.springframework.samples.petclinic.rest.api.OwnersApi;
51	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
52	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
53	import org.springframework.samples.petclinic.rest.dto.PetDto;
54	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
55	import org.springframework.samples.petclinic.rest.dto.VisitDto;
56	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
57	import org.springframework.samples.petclinic.service.ClinicService;
58	import org.springframework.security.access.prepost.PreAuthorize;
59	import org.springframework.web.bind.annotation.CrossOrigin;
60	import org.springframework.web.bind.annotation.RequestMapping;
61	import org.springframework.web.bind.annotation.RestController;
62	import org.springframework.web.util.UriComponentsBuilder;
63	
64	import jakarta.transaction.Transactional;
65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that
77	     * contains at least one dot, with no whitespace anywhere. Deliberately lenient — it accepts
78	     * ordinary addresses while rejecting clearly malformed ones such as {@code not-an-email}.
79	     */
80	    private static final Pattern EMAIL_PATTERN =
81	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
82	
83	    /**
84	     * Dedicated audit logger. On a successful create an audit line carrying the owner id, the
85	     * customerCode, the registrationDate and the membershipLevel is emitted through this logger.
86	     */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    /**
123	     * Rejects an owner payload that is missing or blank in any required field, listing the name of
124	     * each offending field so the caller receives a 400 with a populated {@code errors} array.
125	     */
126	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
127	        List<String> missing = new ArrayList<>();
128	        if (isBlank(ownerFieldsDto.getFirstName())) {
129	            missing.add("firstName");
130	        }
131	        if (isBlank(ownerFieldsDto.getLastName())) {
132	            missing.add("lastName");
133	        }
134	        if (isBlank(ownerFieldsDto.getAddress())) {
135	            missing.add("address");
136	        }
137	        if (isBlank(ownerFieldsDto.getCity())) {
138	            missing.add("city");
139	        }
140	        if (isBlank(ownerFieldsDto.getTelephone())) {
141	            missing.add("telephone");
142	        }
143	        if (!missing.isEmpty()) {
144	            throw new RequiredFieldsMissingException(missing);
145	        }
146	    }
147	
148	    private static boolean isBlank(String value) {
149	        return value == null || value.isBlank();
150	    }
151	
152	    /**
153	     * Normalizes an address on create: leading/trailing whitespace is trimmed, every run of internal
154	     * whitespace is collapsed to a single space, the value is upper-cased and common abbreviations are
155	     * expanded token-by-token ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The
156	     * normalized value is what gets stored, returned and used for every address comparison; a value
157	     * that is blank (or {@code null}) normalizes to the empty string so the required-field check
158	     * rejects it.
159	     *
160	     * @param address the raw address as supplied by the caller, may be {@code null}
161	     * @return the normalized address ({@code ""} when blank or {@code null})
162	     */
163	    private static String normalizeAddress(String address) {
164	        if (address == null) {
165	            return "";
166	        }
167	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
168	        if (collapsed.isEmpty()) {
169	            return "";
170	        }
171	        String[] tokens = collapsed.split(" ");
172	        StringBuilder sb = new StringBuilder(collapsed.length());
173	        for (int i = 0; i < tokens.length; i++) {
174	            String token = tokens[i];
175	            switch (token) {
176	                case "ST" -> token = "STREET";
177	                case "RD" -> token = "ROAD";
178	                case "AVE" -> token = "AVENUE";
179	                default -> { }
180	            }
181	            if (i > 0) {
182	                sb.append(' ');
183	            }
184	            sb.append(token);
185	        }
186	        return sb.toString();
187	    }
188	
189	    /**
190	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
191	     * A leading {@code +} and its country code are kept as given; otherwise the country code
192	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
193	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
194	     * is recognized the national number must have the exact length that code requires ({@code +61}
195	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
196	     * returned.
197	     *
198	     * @param telephone the raw telephone as supplied by the caller
199	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
200	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
201	     *     national-number length is wrong for its country code
202	     */
203	    private static String normalizeTelephone(String telephone) {
204	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
205	        String e164;
206	        if (cleaned.startsWith("+")) {
207	            e164 = "+" + cleaned.substring(1);
208	        } else {
209	            String national = cleaned;
210	            if (national.startsWith("0")) {
211	                national = national.substring(1);
212	            }
213	            e164 = "+61" + national;
214	        }
215	        String digits = e164.substring(1);
216	        if (!digits.matches("\\d{8,15}")) {
217	            throw new InvalidTelephoneException(
218	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
219	        }
220	        if (digits.startsWith("61")) {
221	            requireNationalLength(digits.substring(2), 9, "+61");
222	        } else if (digits.startsWith("1")) {
223	            requireNationalLength(digits.substring(1), 10, "+1");
224	        }
225	        return e164;
226	    }
227	
228	    /**
229	     * Enforces that the national portion of an E.164 number has the exact number of digits its
230	     * country code requires.
231	     *
232	     * @param national the national-number digits (the part after the country code)
233	     * @param expected the exact national-number length the country code requires
234	     * @param countryCode the country code, for the error message
235	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
236	     */
237	    private static void requireNationalLength(String national, int expected, String countryCode) {
238	        if (national.length() != expected) {
239	            throw new InvalidTelephoneException(
240	                "Telephone with country code '" + countryCode + "' must have " + expected
241	                    + " national digits");
242	        }
243	    }
244	
245	    /**
246	     * Normalizes an optional email. An absent or blank email is left unset (returns {@code null});
247	     * a present value must be a syntactically valid address and is stored and returned lower-cased.
248	     *
249	     * @param email the raw email as supplied by the caller, may be {@code null}
250	     * @return the lower-cased email, or {@code null} when none was supplied
251	     * @throws InvalidEmailException if a value is present but is not a syntactically valid address
252	     */
253	    private static String normalizeEmail(String email) {
254	        if (email == null || email.isBlank()) {
255	            return null;
256	        }
257	        String trimmed = email.trim();
258	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
259	            throw new InvalidEmailException("Email must be a syntactically valid address");
260	        }
261	        return trimmed.toLowerCase(Locale.ROOT);
262	    }
263	
264	    /**
265	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
266	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
267	     * householdId}, where the email segment is the empty string when the owner has no email. Because
268	     * the telephone is part of the key, two owners that differ in any one segment (for example two
269	     * members of the same household with different telephones) produce different keys.
270	     *
271	     * @param normalizedTelephone the E.164 telephone of the owner
272	     * @param email the lower-cased email of the owner, may be {@code null}
273	     * @param householdId the stable household identifier of the owner, may be {@code null}
274	     * @return the derived identity key
275	     */
276	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
277	        return (normalizedTelephone == null ? "" : normalizedTelephone)
278	            + "|" + (email == null ? "" : email)
279	            + "|" + (householdId == null ? "" : householdId);
280	    }
281	
282	    /**
283	     * Rejects a create only when the new owner's whole {@code identityKey} equals that of an existing
284	     * owner. This one check replaces the former separate telephone, email and household duplicate
285	     * checks: only an exact full-key match is a duplicate, so two owners that differ in any single
286	     * segment are both allowed. Each existing owner's key is derived from its stored, already
287	     * normalized telephone, email and household identifier.
288	     *
289	     * @param identityKey the derived identity key of the owner being created
290	     * @throws DuplicateIdentityException if another owner already has this identity key
291	     */
292	    private void rejectDuplicateIdentity(String identityKey) {
293	        boolean inUse = this.clinicService.findAllOwners().stream()
294	            .anyMatch(existing -> identityKey.equals(
295	                deriveIdentityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
296	        if (inUse) {
297	            throw new DuplicateIdentityException(
298	                "An owner with the same identity key already exists");
299	        }
300	    }
301	
302	    /**
303	     * Rejects a create when an existing owner already belongs to the same household (i.e. carries the
304	     * same computed {@code householdId}, derived from last name and postcode), unless the request
305	     * knowingly opts in via {@code sharesHousehold}. Setting {@code sharesHousehold} bypasses this
306	     * block so the owner is created as a declared member of the existing household; without it, a
307	     * second owner in the same household is a conflict.
308	     *
309	     * @param householdId the computed household identifier of the owner being created
310	     * @param sharesHousehold whether the request opted in to sharing an existing household
311	     * @throws DuplicateHouseholdException if the household already exists and the request did not opt in
312	     */
313	    private void rejectDuplicateHousehold(String householdId, boolean sharesHousehold) {
314	        if (sharesHousehold) {
315	            return;
316	        }
317	        boolean exists = this.clinicService.findAllOwners().stream()
318	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
319	        if (exists) {
320	            throw new DuplicateHouseholdException(
321	                "An owner with the same last name and postcode already exists");
322	        }
323	    }
324	
325	    /**
326	     * Finds a soft-match "possible duplicate" for the owner being created: an existing owner that is
327	     * not a hard identity duplicate but shares this owner's last name (compared case-insensitively) and
328	     * postcode while carrying a different telephone. When the postcode is absent no owner can share it,
329	     * so there is never a match. When several existing owners qualify the one with the lowest id is
330	     * returned, so the result is deterministic.
331	     *
332	     * @param lastName the last name of the owner being created
333	     * @param postcode the postcode of the owner being created, may be {@code null}
334	     * @param normalizedTelephone the E.164 telephone of the owner being created
335	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
336	     */
337	    private Integer findPossibleDuplicateOf(String lastName, String postcode, String normalizedTelephone) {
338	        if (postcode == null || postcode.isBlank()) {
339	            return null;
340	        }
341	        String normalizedLastName = normalizeName(lastName);
342	        return this.clinicService.findAllOwners().stream()
343	            .filter(existing -> normalizedLastName.equals(normalizeName(existing.getLastName())))
344	            .filter(existing -> postcode.equals(existing.getPostcode()))
345	            .filter(existing -> !normalizedTelephone.equals(existing.getTelephone()))
346	            .map(Owner::getId)
347	            .filter(java.util.Objects::nonNull)
348	            .min(Integer::compareTo)
349	            .orElse(null);
350	    }
351	
352	    /**
353	     * Derives the stable household identifier for an owner from its last name and postcode. The value
354	     * is the first twelve hex characters of the SHA-256 of {@code normalizedLastName + '|' + postcode}
355	     * (the last name normalized case-insensitively with surrounding whitespace trimmed; an absent
356	     * postcode contributes the empty string). Because it is a pure function of those two fields, every
357	     * owner with the same last name and postcode is assigned the same identifier automatically, without
358	     * any existing record having to be updated.
359	     *
360	     * @param lastName the last name of the owner being created
361	     * @param postcode the postcode of the owner being created, may be {@code null}
362	     * @return the stable household identifier
363	     */
364	    private static String householdId(String lastName, String postcode) {
365	        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
366	        return sha256HexPrefix(key, 12);
367	    }
368	
369	    /**
370	     * The maximum number of owners a single city may contain. A create whose city already holds this
371	     * many owners is rejected, so a city never grows beyond this capacity.
372	     */
373	    private static final int CITY_CAPACITY = 50;
374	
375	    /**
376	     * Rejects a create whose city already contains {@link #CITY_CAPACITY} or more owners, so no city
377	     * ever exceeds its capacity. Cities are compared case-insensitively with surrounding whitespace
378	     * trimmed. The count reflects the
379	     * state before the new owner is persisted, so it excludes the owner being created.
380	     *
381	     * @param city the city of the owner being created
382	     * @throws CityAtCapacityException if the city already contains {@link #CITY_CAPACITY} owners
383	     */
384	    private void rejectCityAtCapacity(String city) {
385	        String normalizedCity = normalizeName(city);
386	        long ownersInCity = this.clinicService.findAllOwners().stream()
387	            .filter(existing -> normalizedCity.equals(normalizeName(existing.getCity())))
388	            .count();
389	        if (ownersInCity >= CITY_CAPACITY) {
390	            throw new CityAtCapacityException(
391	                "The city already contains the maximum number of owners");
392	        }
393	    }
394	
395	    /**
396	     * The maximum number of owners that may be created on a single day. A create made once this many
397	     * owners already carry today's {@code registrationDate} is rejected, so no more than this many
398	     * owners are registered per day.
399	     */
400	    private static final int DAILY_OWNER_LIMIT = 100;
401	
402	    /**
403	     * Rejects a create once {@link #DAILY_OWNER_LIMIT} or more owners have already been created for
404	     * the given business day, counted by {@code registrationDate} equal to the effective (weekend
405	     * rolled forward) registration date of the owner being created. The count reflects the state
406	     * before the new owner is persisted, so it excludes the owner being created.
407	     *
408	     * @param registrationDate the effective business-day registration date of the owner being created
409	     * @throws DailyOwnerLimitExceededException if the day already holds {@link #DAILY_OWNER_LIMIT} owners
410	     */
411	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
412	        long ownersToday = this.clinicService.findAllOwners().stream()
413	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
414	            .count();
415	        if (ownersToday >= DAILY_OWNER_LIMIT) {
416	            throw new DailyOwnerLimitExceededException(
417	                "The maximum number of owners for today has already been reached");
418	        }
419	    }
420	
421	    /**
422	     * The number of owners that may already exist for a business day before a create is flagged with
423	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
424	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
425	     */
426	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
427	
428	    /**
429	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
430	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
431	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
432	     * date of the owner being created. The count reflects the state before the new owner is persisted,
433	     * so it excludes the owner being created.
434	     *
435	     * @param registrationDate the effective business-day registration date of the owner being created
436	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
437	     */
438	    private boolean bulkSignupWarning(LocalDate registrationDate) {
439	        long ownersToday = this.clinicService.findAllOwners().stream()
440	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
441	            .count();
442	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
443	    }
444	
445	    /**
446	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
447	     * following Monday, any weekday is returned unchanged.
448	     *
449	     * @param date the effective registration date, supplied or defaulted to the server date
450	     * @return the same date when it is a weekday, otherwise the next Monday
451	     */
452	    private static LocalDate toBusinessDay(LocalDate date) {
453	        DayOfWeek dayOfWeek = date.getDayOfWeek();
454	        if (dayOfWeek == DayOfWeek.SATURDAY) {
455	            return date.plusDays(2);
456	        }
457	        if (dayOfWeek == DayOfWeek.SUNDAY) {
458	            return date.plusDays(1);
459	        }
460	        return date;
461	    }
462	
463	    /**
464	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
465	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
466	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
467	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
468	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
469	     * component: the identity is a pure region-and-hash value.
470	     *
471	     * @param postcode the postcode of the owner being created, may be {@code null}
472	     * @param normalizedTelephone the E.164 telephone of the owner being created
473	     * @param lastName the last name of the owner being created
474	     * @return the formatted customer code
475	     */
476	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
477	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
478	    }
479	
480	    /**
481	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
482	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
483	     * {@code null}, non-numeric, or in no known range.
484	     *
485	     * @param postcode the postcode, may be {@code null}
486	     * @return the region code, or {@code 'UNKNOWN'}
487	     */
488	    private static String regionFromPostcode(String postcode) {
489	        if (postcode == null || postcode.isBlank()) {
490	            return "UNKNOWN";
491	        }
492	        int code;
493	        try {
494	            code = Integer.parseInt(postcode.trim());
495	        } catch (NumberFormatException e) {
496	            return "UNKNOWN";
497	        }
498	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
499	            int[] range = entry.getValue();
500	            if (code >= range[0] && code <= range[1]) {
501	                return entry.getKey();
502	            }
503	        }
504	        return "UNKNOWN";
505	    }
506	
507	    /**
508	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
509	     * upper-cased.
510	     *
511	     * @param value the string to hash
512	     * @param length the number of leading hex characters to return
513	     * @return the upper-cased hex prefix of the digest
514	     */
515	    private static String sha256HexPrefix(String value, int length) {
516	        try {
517	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
518	            StringBuilder sb = new StringBuilder(digest.length * 2);
519	            for (byte b : digest) {
520	                sb.append(String.format("%02x", b));
521	            }
522	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
523	        } catch (NoSuchAlgorithmException e) {
524	            throw new IllegalStateException("SHA-256 not available", e);
525	        }
526	    }
527	
528	    /**
529	     * Counts the existing owners that share the owner-to-be's first and last name, compared
530	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
531	     * new owner is persisted, so it excludes the owner being created.
532	     *
533	     * @param firstName the first name of the owner being created
534	     * @param lastName the last name of the owner being created
535	     * @return the number of existing owners with the same first and last name
536	     */
537	    private int countNamesakes(String firstName, String lastName) {
538	        String normalizedFirstName = normalizeName(firstName);
539	        String normalizedLastName = normalizeName(lastName);
540	        return (int) this.clinicService.findAllOwners().stream()
541	            .filter(existing ->
542	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
543	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
544	            .count();
545	    }
546	
547	    /**
548	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
549	     * number of existing owners already carrying the same {@code householdId}. The household
550	     * identifier is a deterministic function of last name and postcode, so a solo owner (the only one
551	     * with that identifier) is a household of one. The count includes the owner being created (hence
552	     * the {@code + 1}).
553	     *
554	     * @param householdId the stable household identifier of the owner being created
555	     * @return the number of household members after this create (always at least 1)
556	     */
557	    private int householdSize(String householdId) {
558	        if (householdId == null) {
559	            return 1;
560	        }
561	        return (int) this.clinicService.findAllOwners().stream()
562	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
563	            .count() + 1;
564	    }
565	
566	    /**
567	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
568	     * lower-casing.
569	     *
570	     * @param value the raw name, may be {@code null}
571	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
572	     */
573	    private static String normalizeName(String value) {
574	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
575	    }
576	
577	    /**
578	     * The fixed city-to-region table used to validate a postcode against its city
579	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
580	     * therefore accepts any 4-digit postcode.
581	     */
582	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
583	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
584	
585	    /**
586	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
587	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
588	     */
589	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
590	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
591	
592	    /**
593	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
594	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
595	     * when the city maps to a known region, must fall within that region's inclusive range
596	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
597	     * postcode.
598	     *
599	     * @param city the city of the owner being created
600	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
601	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
602	     *     for the city's region
603	     */
604	    private static void validatePostcode(String city, String postcode) {
605	        if (postcode == null || postcode.isBlank()) {
606	            return;
607	        }
608	        if (!postcode.matches("\\d{4}")) {
609	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
610	        }
611	        String region = CITY_REGION.get(city);
612	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
613	        if (range != null) {
614	            int value = Integer.parseInt(postcode);
615	            if (value < range[0] || value > range[1]) {
616	                throw new InvalidPostcodeException(
617	                    "Postcode is out of range for the city's region");
618	            }
619	        }
620	    }
621	
622	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
623	    @Override
624	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
625	        Owner owner = this.clinicService.findOwnerById(ownerId);
626	        if (owner == null) {
627	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
628	        }
629	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
630	    }
631	
632	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
633	    @Override
634	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
635	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
636	        validateRequiredFields(ownerFieldsDto);
637	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
638	        if (registrationDate == null) {
639	            registrationDate = LocalDate.now();
640	        } else if (registrationDate.isAfter(LocalDate.now())) {
641	            throw new FutureRegistrationDateException(
642	                "registrationDate must not be later than the server date");
643	        }
644	        registrationDate = toBusinessDay(registrationDate);
645	        ownerFieldsDto.setRegistrationDate(registrationDate);
646	        rejectDailyOwnerLimit(registrationDate);
647	        rejectCityAtCapacity(ownerFieldsDto.getCity());
648	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
649	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
650	        ownerFieldsDto.setTelephone(normalizedTelephone);
651	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
652	        ownerFieldsDto.setEmail(normalizedEmail);
653	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
654	        String ownerHouseholdId = householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
655	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
656	        rejectDuplicateHousehold(ownerHouseholdId, sharesHousehold);
657	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(
658	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(), normalizedTelephone);
659	        HttpHeaders headers = new HttpHeaders();
660	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
661	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
662	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
663	        owner.setCustomerCode(customerCode(
664	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName()));
665	        owner.setHouseholdId(ownerHouseholdId);
666	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
667	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
668	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
669	        this.clinicService.saveOwner(owner);
670	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
671	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
672	            ownerMapper.membershipLevel(owner));
673	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
674	        headers.setLocation(UriComponentsBuilder.newInstance()
675	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
676	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
677	    }
678	
679	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
680	    @Override
681	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
682	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
683	        if (currentOwner == null) {
684	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
685	        }
686	        currentOwner.setAddress(ownerFieldsDto.getAddress());
687	        currentOwner.setCity(ownerFieldsDto.getCity());
688	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
689	        currentOwner.setLastName(ownerFieldsDto.getLastName());
690	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
691	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
692	        this.clinicService.saveOwner(currentOwner);
693	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
694	    }
695	
696	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
697	    @Transactional
698	    @Override
699	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
700	        Owner owner = this.clinicService.findOwnerById(ownerId);
701	        if (owner == null) {
702	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
703	        }
704	        this.clinicService.deleteOwner(owner);
705	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
706	    }
