708	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
709	    @Override
710	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
711	        Owner owner = this.clinicService.findOwnerById(ownerId);
712	        if (owner == null) {
713	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
714	        }
715	        HttpHeaders headers = new HttpHeaders();
716	        Pet pet = petMapper.toPet(petFieldsDto);
717	        owner.setId(ownerId);
718	        pet.setOwner(owner);
719	        pet.getType().setName(null);
